   int gNextIndex = 1;
   ed::EditorContext* gEditor = nullptr;
   GraphNode* gSelfTestFeeder = nullptr;
   bool gPaletteTestOk = false;    // dev test only
   bool gPaletteTestPending = false;
   ImVec2 gSpawnPos(0.0f, 0.0f);

