   struct LinkInfo
   {
      int id = 0;
      int srcPin = 0;
      int dstPin = 0;
   };
   const int kLinkIdBase = 4000000; // far above any node/pin id
   std::vector<LinkInfo> gLinks;

   const LinkInfo* FindLink(int id)
   {
      for (const LinkInfo& link : gLinks)
      {
         if (link.id == id)
            return &link;
      }
      return nullptr;
   }

   // Dynamic pins, Phase 1 (build step 11, decision 4): toggling a menu entry
   // off while a live cable is attached to the output pin it would remove
   // must be refused rather than silently orphaning the cable. gLinks is
   // rebuilt earlier in this same frame (see CaptureClusterLinks' comment
   // above), so this reads current topology, not last frame's.
   bool FieldOutputPinHasLiveCable(int nodeIndex, int outputIndex)
   {
      for (const LinkInfo& link : gLinks)
      {
         if (!GraphNode::IsOutputPin(link.srcPin))
            continue;
         if (GraphNode::NodeIndexFromPin(link.srcPin) == nodeIndex &&
             GraphNode::OutputIndexFromPin(link.srcPin) == outputIndex)
            return true;
      }
      return false;
   }

   // Dynamic pins, Phase 2b (build step 13, §5.1): symmetric to
   // FieldOutputPinHasLiveCable above, but scans destination (input) pins -
   // needed so a kernel edit that would retire a declared `input` pin (not
   // just a declared `output`) can refuse rather than silently orphan
   // whatever is wired into it.
   bool FieldInputPinHasLiveCable(int nodeIndex, int inputIndex)
   {
      for (const LinkInfo& link : gLinks)
      {
         if (!GraphNode::IsInputPin(link.dstPin))
            continue;
         if (GraphNode::NodeIndexFromPin(link.dstPin) == nodeIndex &&
             GraphNode::InputSlotFromPin(link.dstPin) == inputIndex)
            return true;
      }
      return false;
   }

   // Bridge installed into Field::gLiveCableChecker (see PinTable.h) so
   // Field*Node::Apply() - compiled in separate translation units, and
   // never able to see gLinks (private to this anonymous namespace) - can
   // still ask "does this pin's current compacted slot have a live cable".
   // Taking the address of an internal-linkage function and storing it in
   // an externally-linked function pointer is legal; only the pointer
   // itself needs external linkage.
   bool CheckFieldLiveCableBridge(int nodeIndex, int slot, bool isOutput)
   {
      return isOutput ? FieldOutputPinHasLiveCable(nodeIndex, slot) : FieldInputPinHasLiveCable(nodeIndex, slot);
   }

   void DisconnectLinkById(int id); // forward decl - defined below, used by the bridge just after it

   // Sibling bridge to CheckFieldLiveCableBridge, installed into
   // Field::gLiveCableDisconnector - severs every live cable on the given
   // pin at its real node-graph source (same DisconnectLinkById used by
   // interactive cable delete) instead of refusing the reconcile. gLinks is
   // rebuilt from live node pointers every frame (see its own comment), so
   // clearing the pointer here is enough - no separate ed:: bookkeeping
   // needed for the change to stick on the next frame.
   void DisconnectFieldPinBridge(int nodeIndex, int slot, bool isOutput)
   {
      std::vector<int> ids;
      for (const LinkInfo& link : gLinks)
      {
         if (isOutput)
         {
            if (GraphNode::IsOutputPin(link.srcPin) &&
                GraphNode::NodeIndexFromPin(link.srcPin) == nodeIndex &&
                GraphNode::OutputIndexFromPin(link.srcPin) == slot)
               ids.push_back(link.id);
         }
         else
         {
            if (GraphNode::IsInputPin(link.dstPin) &&
                GraphNode::NodeIndexFromPin(link.dstPin) == nodeIndex &&
                GraphNode::InputSlotFromPin(link.dstPin) == slot)
               ids.push_back(link.id);
         }
      }
      for (int id : ids)
         DisconnectLinkById(id);
   }
   bool gSnapToGrid = true;
   float gGridSnap = 20.0f;
   // Audio device/rate/buffer selection, applied to AudioEngine on next
   // Start(). 0 / 0.0 mean "system default" - see
   // Platform::AudioDeviceOpen's doc comment in Platform.h. Session-only,
   // same as every other setting in the "Menu" menu (no settings
   // persistence exists anywhere in this codebase yet).
   uint32_t gAudioOutputDeviceId = 0;
   uint32_t gAudioInputDeviceId = 0;
   double gAudioSampleRate = 0.0;
   int gAudioBufferFrames = 512;
   // Placeholder only - no DSP node reads this yet. P3c's Drive/AudioFilter
   // kernels are the intended future consumer (see README.md's Effects
   // table); this phase just makes the setting exist and be visible.
   float gAudioOversample = 1.0f;
   // Set whenever a Start() call from the toolbar toggle or "Apply audio
   // settings" fails, so the toggle button can surface why on hover instead
   // of just silently staying off. Cleared on a successful Start().
   std::string gAudioStartError;

   // ---- Offline Render (non-realtime export) state ----
   // One take at a time, across the whole patch (not per-OutputNode) - the
   // graph and AudioEngine are only ever driven by one clock at once, so two
   // Output nodes each trying to run their own offline session concurrently
   // would just race each other over the same Transport/AudioEngine calls.
   struct OfflineRenderState
   {
      bool active = false;         // a take is either rendering or finalizing
      OutputNode* node = nullptr;  // which OutputNode owns this take
      bool includeAudio = false;   // latched at start, mirrors node->includeAudio
      bool deviceWasRunning = false; // AudioEngine::Instance().SampleRate() > 0 before this take
      bool wasPlaying = true;        // Transport::Instance().IsPlaying() before this take
      bool vsyncWasOn = true;        // gVsync before this take; restored when it ends
      double startTime = 0.0;        // glfwGetTime() when the take was armed
      double startSeconds = 0.0;     // Transport::Instance().Seconds() when take was armed
      // Set by the pump whenever it yields because the encoder queue is full
      // rather than because it ran out of time budget. The two look identical
      // from outside - the frame counter stops either way - so the progress
      // window says which one is happening instead of leaving the user to
      // guess whether a render is slow or wedged.
      bool waitingOnEncoder = false;
      double lastProgressTime = 0.0; // when OfflineFramesDone last changed
      int lastFramesDone = -1;

      // Set only for a render started from the Arrangement Timeline's own
      // Render button - switches on two behaviors that would be wrong for
      // an ordinary manually-wired OutputNode take: (1) each frame, every
      // video lane's active clip is composited onto the node's FBO after
      // the cook (CompositeArrangeTimelineVideo - bottom lane first, so the
      // top lane is frontmost, each lane's blend mode and opacity applied),
      // replacing whatever the node's own Input produced; (2) RebuildAudioTopology's Timeline Strict terminals also
      // write into this node's capture ring (see arrangeAudioCapture
      // below), so the take's audio is the live sum of every active
      // timeline audio clip rather than whatever's cabled into AudioInput.
      bool arrangeDriven = false;
      // WP7 #6b splits arrangeDriven's two behaviours apart, because a job
      // can now take its picture from one place and its sound from another
      // ("video-only timeline over live canvas music" is a first-class job).
      // Both are only read while arrangeDriven.
      //   timelineVideo - composite the video lanes onto the take's FBO,
      //                   replacing whatever its own Input produced.
      //   timelineAudio - RebuildAudioTopology builds the Timeline Strict
      //                   terminals rather than the canvas Audio Outs
      //                   (ArrangeTimelineRoutingActive).
      // Audio always reaches the file through the take node's capture ring
      // either way: the timeline's export node has nothing cabled into its
      // AudioInput, so both sources are the master sum, and only the
      // terminals feeding that sum differ.
      bool timelineVideo = false;
      bool timelineAudio = false;
      // The job's range in ticks. StartOfflineRenderSession scopes its
      // hardware-source refusal (WP7 #4) to the clips that actually play
      // inside it, so it has to be set before the take is armed - same
      // discipline as arrangeDriven and endSeconds.
      int64_t rangeStartTick = 0;
      int64_t rangeEndTick = 0;
      // Only meaningful when arrangeDriven: the timeline second the render
      // should end on, so the render-finish cleanup can park the playhead
      // there instead of leaving it wherever Transport::SetOfflineMode(false)
      // happens to revert to (whatever mSeconds was before the take started).
      double endSeconds = 0.0;
   };
   OfflineRenderState gOfflineRender;

   // ---- Arrangement render jobs (WP7) --------------------------------------
   // One job = one file. The timeline's Render popup fills one in, and either
   // runs it immediately or parks it in the queue; both paths go through
   // ArrangeRenderBeginJob, so the hardware-source refusal, the overwrite
   // check and the source routing can't be skipped by one of them.
   enum ArrangeRenderAudioSource { kArrangeAudioTimeline = 0, kArrangeAudioCanvas = 1, kArrangeAudioNone = 2 };
   enum ArrangeRenderVideoSource { kArrangeVideoTimeline = 0, kArrangeVideoCanvas = 1, kArrangeVideoNone = 2 };
   enum ArrangeRenderRangeKind { kArrangeRangeWhole = 0, kArrangeRangeLoop = 1, kArrangeRangeMarkers = 2, kArrangeRangeCustom = 3 };
   enum ArrangeRenderStatus
   {
      kArrangeJobQueued = 0,
      kArrangeJobRendering,
      kArrangeJobFinalizing,
      kArrangeJobDone,
      kArrangeJobFailed,
      kArrangeJobCancelled
   };

   struct ArrangeRenderJob
   {
      uint64_t id = 0;
      int rangeKind = kArrangeRangeWhole;
      int64_t startTick = 0;
      int64_t endTick = 0;
      int audioSource = kArrangeAudioTimeline;
      int videoSource = kArrangeVideoTimeline;
      uint64_t canvasVideoUid = 0; // only when videoSource == kArrangeVideoCanvas
      int width = 1920, height = 1080, fps = 60;
      int sampleRate = 48000;
      int format = 0;              // 0 = mp4, 1 = mov, 2 = wav
      std::string path;
      int status = kArrangeJobQueued;
      std::string message;         // failure reason, or a note about the take
      int framesDone = 0, framesTotal = 0;
      double startedTime = 0.0;    // glfwGetTime() when it began, for the ETA
      // Empty = whole project (every lane), matching the original behavior.
      // Non-empty scopes the take to just these lane ids ("Render Track" /
      // "Render Group"). Only meaningful when videoSource is Timeline or
      // None - a canvas take isn't a lane concept, so it always ignores this.
      std::vector<uint64_t> laneScope;
   };

   // Read by RebuildAudioTopology's arrangement lane loop and by
   // CollectArrangeVideoLayers while a scoped render job is in flight; empty
   // otherwise. A global flag rather than a threaded parameter because both
   // are also called every frame for live playback, far from any render job.
   std::unordered_set<uint64_t> gArrangeRenderActiveLaneScope;

   // The timeline's own render target. Never a canvas node: an arrangement
   // take composites its lanes onto this node's FBO and nothing else, so it
   // stays off the graph, out of the patch and out of every node list.
   std::unique_ptr<OutputNode> gArrangeTimelineExportNode;

   std::vector<ArrangeRenderJob> gArrangeRenderQueue;
   uint64_t gArrangeRenderNextJobId = 1;
   uint64_t gArrangeRenderActiveJobId = 0; // 0 = nothing in flight
   bool gArrangeRenderQueueRunning = false;

   // An audio-only take (Video source = None). It has no OutputNode, no
   // encoder and no frames - just AudioEngine::ProcessOffline block by block
   // into a WAV file - so it can't ride on gOfflineRender, which is built
   // around a node's video take. Only one of the two ever runs at a time.
   struct ArrangeWavRenderState
   {
      bool active = false;
      bool timelineAudio = true;   // same meaning as gOfflineRender.timelineAudio
      bool cancelRequested = false;
      AudioFileWriter writer;
      long long framesTotal = 0, framesDone = 0;
      double sampleRate = 0.0;
      double startSeconds = 0.0, endSeconds = 0.0;
      bool deviceWasRunning = false, wasPlaying = true, vsyncWasOn = true;
      double startedTime = 0.0;
   };
   ArrangeWavRenderState gArrangeWavRender;

   // Defined next to StartOfflineRenderSession; called from the timeline panel
   // (far above it in file order) and from the main loop's pump (far below).
   bool ArrangeRenderBeginJob(ArrangeRenderJob& job);
   void ArrangeRenderQueueTick();
   void ArrangeRenderCancelActive();
   void ArrangeRenderCancelAll();
   void ArrangeRenderQueuePosition(int& outIndex, int& outTotal);
   bool ArrangeRenderBusy();

   // ---- device-change / sleep-wake recovery state (PollAudioRecovery) ----
   // docs/plans/optimization/prompts/02-device-change-and-wake-recovery.md.
   // Bounds recovery to one attempt per kAudioRecoveryMinIntervalMs and no
   // more than kAudioRecoveryMaxAttemptsPerWindow inside any
   // kAudioRecoveryWindowMs rolling window, so a flapping device or a burst
   // of notifications on wake can't spawn overlapping restarts or loop
   // forever - see PollAudioRecovery's comment for how these are used.
   constexpr double kAudioRecoveryMinIntervalMs = 500.0;
   constexpr double kAudioRecoveryWindowMs = 10000.0;
   constexpr int kAudioRecoveryMaxAttemptsPerWindow = 5;
   double gLastAudioRecoveryAttemptMs = -1.0;
   double gAudioRecoveryWindowStartMs = -1.0;
   int gAudioRecoveryAttemptsInWindow = 0;
   // Test-only reset so INFINITE_AUDIORECOVERYTEST can run more than one
   // scenario in the same process without an earlier scenario's backoff
   // state leaking into the next.
   void ResetAudioRecoveryState()
   {
      gLastAudioRecoveryAttemptMs = -1.0;
      gAudioRecoveryWindowStartMs = -1.0;
      gAudioRecoveryAttemptsInWindow = 0;
   }
   double gLastFrameMs = 0.0; // wall clock across the previous whole frame
   double gFrameStart = 0.0;  // when the current frame began, for the limiter
   // 60 by default: a light patch spinning the GPU at 400fps costs power for
   // nothing, and a predictable budget makes the cost of a setting readable.
   int gTargetFps = 60;       // 0 = uncapped; otherwise the frame limiter's budget
   bool gVsync = true;
   bool gRequestFitView = false;
   // Set by the "fit_view_node" RPC method (documentation screenshot tooling):
   // navigate to one node's own bounds via selection rather than the whole
   // canvas, so a feeder spawned off-screen for auto_wire_inputs never pulls
   // the view out to include it. -1 = no request pending.
   int gRequestFitViewNodeIndex = -1;
   // Set by the Edit menu, consumed next to the matching keyboard shortcuts.
   // The menu bar draws outside ed::Begin/End, and grouping needs the live
   // selection, so both routes meet in one place inside the editor frame
   // rather than the menu reaching into the editor from outside it.
   bool gRequestGroup = false;
   bool gRequestUngroup = false;
   bool gRequestBypass = false;
   bool gRequestCopy = false;
   bool gRequestPaste = false;
   bool gRequestDuplicate = false;
   bool gRequestDelete = false;
   bool gRequestSelectAll = false;
   bool gRequestAddNode = false;
   bool gRequestAddComment = false;
   int gContextMenuNodeIndex = -1; // node the right-click context menu is open for
   int gHelpPopupNodeIndex = -1; // node the per-node "Help" popup is open for
   bool gOpenNodeHelpPopup = false; // set for one frame to open it (can't OpenPopup from inside another popup's Begin/End and have it show the same frame)
   // Which param's modulation-binding menu (Absolute/Bipolar/depth/Unbind) is
   // open. Same reason as gContextMenuNodeIndex/gOpenNodeHelpPopup above: the
   // param slider/knob is drawn deep inside ed::Begin()/ed::End() for that
   // node, which runs under the node editor's own canvas transform - an
   // ImGui::OpenPopup() called there lands at whatever screen position the
   // canvas transform happens to leave the cursor at (and, worse, doesn't
   // reliably receive its own clicks), same as any other popup in this file.
   // So the widget only *records* nodeIndex/paramIndex and a "please open"
   // flag; the popup itself is opened and drawn once, later, inside the
   // ed::Suspend() block alongside "##nodecontext"/"##nodehelp".
   int gModBindingMenuNode = -1;
   int gModBindingMenuParam = -1;
   bool gOpenModBindingMenu = false;
   // Hover-and-type for the ##modbind popup's lo/hi fields, matching the
   // hover+type convention every other param field in this file uses (see
   // gTypedParam) rather than relying on DragFloat/DragInt's own
   // double-click/Ctrl+click text-entry, which is easy to miss since nothing
   // in the popup hints it exists. field: 0=lo, 1=hi, -1=none active.
   int gModRangeTypedField = -1;
   std::string gModRangeTypedText;
   bool gModRangeTypedJustOpened = false;
   // Seeded-digit entry (hover + press a digit key) needs the field to open
   // one frame *after* the keypress rather than the same frame - see
   // gTypedParamPendingInit's comment at BeginTypedEditFromCurrent for why:
   // InputText's own select-all only takes effect once it's confirmed active,
   // which can land a frame after SetKeyboardFocusHere, so driving selection
   // off a flag races with that and produces exactly the double-char/can't-
   // replace-the-seed behaviour this is avoiding.
   bool gModRangeTypedPendingInit = false;
   bool gModRangeTypedNoAutoSelect = false;
   // The node browser lives in a docked panel rather than only the canvas popup,
   // so modules can be found without knowing the double-click gesture exists.
   bool gNodePanelOpen = false;
   // The dockable viewport panel: every node index in this list gets its own
   // card, stacked left-to-right when bottom-docked or top-to-bottom when
   // right/left-docked (see DrawViewportPanelContainer). Serialized to
