      return RunFieldParamTest();

   if (getenv("INFINITE_FIELDSTATETEST") != nullptr)
      return RunFieldStateTest();

   if (getenv("INFINITE_FIELDTRANSFERTEST") != nullptr)
      return RunFieldTransferTest();

