            report.frames = 1;
            report.nodes = (int)nodesBefore;
            report.stagesCpuMs = {
               { "push_checkpoint", tPushEnd - tPushStart },
               { "undo_restore", tUndoEnd - tPushEnd },
            };
            report.memRssEndMb = Bench::ProcessRssMb();
            report.Emit();
            printf("B5UNDO %s DONE\n", restored ? "OK" : "FAIL");
            fflush(stdout);
